const durable = () => buildDurableSnapshot({ projectId: 'project', versionId: 'version', publication });
function bass(level = 4) {
  const contract = structuredClone(bassFixture);
  contract.version = BASS_ANALYSIS_CONTRACT_VERSION;
  contract.metricSchemaVersion = RP22_BASS_METRIC_SCHEMA_VERSION;
  contract.job.metricSchemaVersion = RP22_BASS_METRIC_SCHEMA_VERSION;
  const fp = level === 4 ? 'B118' : 'B115';
  contract.job.resultFingerprint = contract.job.currentJobFingerprint = fp;
  contract.productAnalysis.parameters.p14 = { ...contract.productAnalysis.parameters.p14,
    value: level === 4 ? 118 : 115, level, selectedLevel: level, selectedTargetDb: level === 4 ? 118 : 115 };
  return { status: 'complete', authorityStatus: 'AUTHORITATIVE', authoritative: true,
    exportable: true, structurallyComplete: true, currentFingerprint: fp, contract };
}
test('P10 project floor is 9 dB/L1 from one published seat row', () => {
  const row = readReportParameter(durable().engineeringSummary, 10);
  assert.equal(row.value, '9 dB'); assert.equal(row.level, 'L1');
  assert.equal(row.scope, 'project'); assert.equal(row.authority_fingerprint, publication.engineering_fingerprint);
});
test('Primary P10 is explicitly labelled 3 dB/L3', () => {
  const row = readReportParameter(durable().engineeringSummary, 10, { scope: 'primary' });
  assert.equal(row.value, '3 dB'); assert.equal(row.level, 'L3');
  assert.match(row.text, /^Primary/); assert.equal(row.scope, 'primary');
});
test('Secondary and individual P10 scopes retain their own pair', () => {
  assert.equal(readReportParameter(durable().engineeringSummary, 10, { scope: 'secondary' }).value, '9 dB');
  const row = readReportParameter(durable().engineeringSummary, 10, { scope: 'per-seat', seatId: 'seat-r1-c2' });
  assert.equal(row.value, '3 dB'); assert.equal(row.level, 'L3');
});
test('Aggregate grade cannot override a room source pair', () => {
  const summary = durable().engineeringSummary;
  summary.parameterSummaries.project.p12.level = 'L1';
  assert.equal(readReportParameter(summary, 12).level, summary.roomResultsByParameter[12].level);
});
function overlay(level = 4) {
  const summary = durable().engineeringSummary;
  summary.roomResultsByParameter[14] = { value: 115, formatted: '115 dBC', level: 'L3' };
  return applyRestoredBassAuthority(summary, { projectId: 'project', versionId: 'version', completedBassAuthority: bass(level) });
}
test('B118 replaces old P14 value AND grade', () => {
  const row = readReportParameter(overlay(), 14);
  assert.equal(row.value, '118 dBC'); assert.equal(row.level, 'L4');
  assert.equal(row.authority_fingerprint, 'B118'); assert.equal(row.source_type, 'durable-current-bass-authority');
  assert.ok(row.authority_timestamp);
});
test('B115 is used only when selected as current', () => {
  const row = readReportParameter(overlay(3), 14);
  assert.equal(row.value, '115 dBC'); assert.equal(row.level, 'L3'); assert.equal(row.authority_fingerprint, 'B115');
});
test('Mismatched current bass pointer cannot replace the publication', () => {
  const authority = bass(); authority.currentFingerprint = 'different';
  const summary = applyRestoredBassAuthority(durable().engineeringSummary, { projectId: 'project', versionId: 'version', completedBassAuthority: authority });
  assert.equal(summary.bassAuthorityCurrent, false);
});
test('Final report ignores a mismatched browser handoff', () => {
  const db = durable();
  assert.equal(composeAuthoritySnapshot({ durableSnapshot: db, localSnapshot: { engineeringFingerprint: 'wrong', engineeringSummary: {} }, finalReport: true }), db);
});
test('No durable authority means no final snapshot even with browser values', () => {
  assert.equal(composeAuthoritySnapshot({ durableSnapshot: null, localSnapshot: { engineeringSummary: {} }, finalReport: true }), null);
});
test('Historical publication missing frozen room/screen facts blocks regeneration', () => {
  const result = auditFinalReportAuthority(publication);
  assert.equal(result.allowed, false); assert.ok(result.missing.some(field => field.includes('report_snapshot.report_project')));
  assert.ok(result.missing.some(field => field.includes('publication_contract_version')));
});
function completeEvidence() {
  const parameters = Array.from({ length: 21 }, (_, n) => {
    const id = n + 1, isBass = [14,18,19,20].includes(id);
    const row = { key: 'P' + id, parameter_id: id, scope: id === 10 ? 'project' : 'room',
      value: '1', raw_value: 1, unit: 'dB', level: 'L3', context: 'test authority', limiting_group: null,
      authority_fingerprint: isBass ? 'B118' : 'E', authority_timestamp: '2026-10-04T22:57:57.437Z',
      source_type: isBass ? 'durable-current-bass-authority' : 'durable-engineering-publication' };
    if (id === 10) Object.assign(row, { value: '9 dB', raw_value: 9, level: 'L1' });
    if (id === 14) Object.assign(row, { value: '118 dBC', raw_value: 118, level: 'L4' });
    return { ...row, authority_value: row.value, authority_level: row.level };
  });
  return { evidence_version: 1, report_type: 'technical', proposal_ready: true,
    identity: { project_id: 'project', version_id: 'version', report_type: 'technical', source_fingerprint: 'E', bass_fingerprint: 'B118' },
    room: { length_m: 6, width_m: 4, height_m: 3 },
    screen: { screen_type: 'projection', format: '16:9', viewable_width_cm: 300 },
    system: { products_selected: [{ model: 'test' }] }, parameters,
    parameter_index: Object.fromEntries(parameters.map(row => [row.key, row])),
    bass: { p14: { raw_value: 118, achieved_level: 'L4' } },
    seating: { seats: 1, per_seat: [{ seat_id: 'seat', row: 1, column: 1, priority: 'primary', distance_m: 3, horizontal_angle_deg: 40 }] } };
}
test('Coherent evidence passes identical readiness and server validators', () => {
  const evidence = completeEvidence();
  assert.equal(browser(evidence).complete, true);
  assert.deepEqual(browser(evidence), server(evidence));
});
for (const [label, mutate] of [
  ['wrong fingerprint', e => e.parameter_index.P14.authority_fingerprint = 'B115'],
  ['mixed P14 value and grade', e => e.parameter_index.P14.raw_value = 115],
  ['mixed P10 scope/value', e => Object.assign(e.parameter_index.P10, { value: '3 dB', raw_value: 3 })],
  ['browser source', e => e.parameter_index.P12.source_type = 'browser-handoff'],
  ['missing timestamp', e => e.parameter_index.P13.authority_timestamp = null],
  ['index and row disagree', e => e.parameter_index.P13 = { ...e.parameter_index.P13, value: 'different' }],
]) test(label + ' blocks readiness and server with the same reason', () => {
  const evidence = completeEvidence(); mutate(evidence);
  assert.equal(browser(evidence).complete, false);
  assert.deepEqual(browser(evidence), server(evidence));
});
